-- ① Slice 로 아예 안 센다

public interface MemberRepositoryCustom {
    Slice<MemberTeamDto> searchSlice(MemberSearchCondition cond,
                                     Pageable pageable);
}

@Override
public Slice<MemberTeamDto> searchSlice(MemberSearchCondition cond,
                                        Pageable pageable) {
    BooleanExpression predicate = Expressions.allOf(
            usernameEq(cond.getUsername()),
            ageBetween(cond.getAgeGoe(), cond.getAgeLoe()));

    List<MemberTeamDto> content = queryFactory
            .select(new QMemberTeamDto(
                    member.id, member.username, member.age,
                    team.id, team.name))
            .from(member)
            .leftJoin(member.team, team)
            .where(predicate)
            .orderBy(member.id.asc())
            .offset(pageable.getOffset())
            .limit(pageable.getPageSize() + 1)      // 한 건 더
            .fetch();

    boolean hasNext = content.size() > pageable.getPageSize();
    if (hasNext) {
        content.remove(content.size() - 1);
    }
    return new SliceImpl<>(content, pageable, hasNext);
}

