-- 네 방법을 나란히 잰다

@Test
@Transactional
void 네_방법() {
    MemberSearchCondition cond = new MemberSearchCondition();
    cond.setAgeGoe(20);
    PageRequest req = PageRequest.of(5, 20);

    record C(String name, Runnable r) {}
    for (C c : List.of(
            new C("무거운 개수", () ->
                    memberRepository.searchPageHeavy(cond, req)),
            new C("가벼운 개수", () ->
                    memberRepository.searchPageComplex(cond, req)),
            new C("Slice",      () ->
                    memberRepository.searchSlice(cond, req)))) {
        em.clear();
        sqlCounter.clear();
        long t = System.nanoTime();
        c.r().run();
        System.out.printf("%-12s %d개 %d ms%n", c.name(),
                sqlCounter.count(), (System.nanoTime() - t) / 1_000_000);
    }
}

