-- 커서로 가면 오프셋도 없다

@Override
public Slice<MemberTeamDto> searchCursor(Long lastId, int size) {
    List<MemberTeamDto> content = queryFactory
            .select(new QMemberTeamDto(
                    member.id, member.username, member.age,
                    team.id, team.name))
            .from(member)
            .leftJoin(member.team, team)
            .where(lastId == null ? null : member.id.gt(lastId))
            .orderBy(member.id.asc())
            .limit(size + 1)
            .fetch();

    boolean hasNext = content.size() > size;
    if (hasNext) content.remove(content.size() - 1);
    return new SliceImpl<>(content, Pageable.unpaged(), hasNext);
}

@Test
@Transactional
void 커서() {
    em.clear();
